const AFEAT = [['Kalendarz rezerwacji','Kontroluj dostępność kortów i bieżący grafik z jednego panelu. Edytuj, przenoś i anuluj rezerwacje.'],['Rezerwacje online','Gracze rezerwują sami: w aplikacji, na neopadel.app i przez widżet na stronie klubu. Mniej telefonów i wiadomości.'],['Płatności','Rezerwacja połączona z płatnością online. Mniej ręcznie obsługiwanych transakcji.'],['Zarządzanie graczami','Najważniejsze informacje o klientach w jednym miejscu: historia aktywności i rezerwacji.'],['Cennik i dostępność','Godziny, stawki, poziomy cenowe, promocje i zasady rezerwacji. Szczyt i godziny o niższym obłożeniu.'],['Turnieje i wydarzenia','Zapisy, lista graczy, harmonogram, format rozgrywek, wyniki i komunikacja z uczestnikami.']];
