const KMODELS = [['panorama','Panorama','Uniwersalny','20 × 10 m · słupki wyłącznie w narożnikach','Połączenie estetyki, funkcjonalności i trwałości. Nowoczesny, otwarty wygląd i wysoka stabilność.',['Nowe kluby','Obiekty wewnętrzne i zewnętrzne','Realizacje wymagające dobrej widoczności']],['super','Super Panorama','Premium','20 × 10 m · bez słupów na przeszkleniach','Kort, który przyciąga uwagę. Wizualnie lekka konstrukcja i maksymalna widoczność dla widzów.',['Hale padlowe i court central','Kluby premium','Wydarzenia i turnieje']],['titan','Titan','Wzmocniony','20 × 10 m · wzmocniona rama stalowa','Mocniejsza konstrukcja do miejsc, gdzie kort musi znieść więcej: wiatr i trudne warunki.',['Plener w otwartym terenie','Wybrzeże i góry','Intensywnie użytkowane obiekty']],['singiel','Single','Kompaktowy','20 × 6 m · gra jeden na jednego','Maksymalne wykorzystanie dostępnej przestrzeni. Idealny jako dodatkowa strefa treningowa.',['Treningi indywidualne','Ograniczona powierzchnia','Uzupełnienie kompleksu']]];
