 + dSec('System', 'Najważniejsze elementy kortu działają *jako jeden system.*', tiles([['Dostęp', 'Automatyczne otwieranie i zamykanie drzwi zgodnie z ustalonym harmonogramem.'], ['Oświetlenie', 'Sterowanie światłem w zależności od czasu rezerwacji oraz pory dnia.'], ['Sygnały dźwiękowe', 'System przypomina graczom o zakończeniu czasu przeznaczonego na rezerwację.'], ['Bezpieczeństwo', 'Przycisk bezpieczeństwa pozwala opuścić kort także po automatycznym zablokowaniu drzwi.'], ['Sterowanie manualne', 'Właściciel może w razie potrzeby ręcznie sterować dostępem i oświetleniem.']], 'five'))
 + `<section class="dark-section k-sec" id="jak-dziala"><div class="wrap"><div class="k-head"><span class="eyebrow">Scenariusz działania</span>${kin('Od rezerwacji *do gotowego kortu.*')}<p class="k-lead">Gracz ma zarezerwowany kort na 13:00. System rozpoznaje zaplanowany czas gry i uruchamia scenariusz.</p></div>${steps([['Przed rezerwacją', 'W ustalonym czasie przed grą zostaje umożliwiony dostęp do kortu.'], ['Start rezerwacji', 'Kort gotowy. Oświetlenie działa według zasad i pory dnia.'], ['Czas gry', 'System kontroluje czas przypisany do rezerwacji.'], ['Koniec rezerwacji', 'Rusza zaprogramowana sekwencja sygnałów dźwiękowych.'], ['Czas na wyjście', 'Gracze mają kilka minut na zakończenie gry i wyjście.'], ['Drzwi zablokowane', 'Kort przygotowuje się do kolejnej rezerwacji.']])}</div></section>`
 + dSec('Sygnały', 'Kort sam informuje *o zakończeniu gry.*', `<p class="k-lead d-lead">System nie zamyka dostępu od razu. Gracze mają czas na dokończenie gry, zebranie rzeczy i bezpieczne wyjście.</p><div class="d-signals" data-reveal>${[['Koniec rezerwacji', 'Czas gry upływa.'], ['+3 minuty', 'Trzy krótkie sygnały dźwiękowe.'], ['+4 minuty', 'Ponowne sygnały przypominające.'], ['ok. +5 minut', 'Długi sygnał końcowy.'], ['Drzwi zablokowane', 'Automatyczne zamknięcie po sekwencji.']].map(([t, d], i) => `<div style="--i:${i}"><b>${t}</b><span>${d}</span></div>`).join('')}</div>`)
 + `<section class="dark-section k-sec"><div class="wrap d-two" data-reveal><article class="tile"><span class="eyebrow">Bezpieczne wyjście</span><h3>Automatyczne zamknięcie. Bezpieczne wyjście.</h3><p>Jeżeli ktoś zostanie na korcie po zablokowaniu drzwi, przycisk bezpieczeństwa wewnątrz pozwala otworzyć drzwi od środka. Automatyzacja dostępu nie może uniemożliwić opuszczenia kortu.</p></article><article class="tile"><span class="eyebrow">Oświetlenie</span><h3>Światło dopasowane do rzeczywistych warunków.</h3><ul class="k-list"><li>Stałe godziny działania oświetlenia</li><li>Automatycznie według wschodu i zachodu słońca w lokalizacji klubu</li><li>Manualne włączenie lub wyłączenie w razie potrzeby</li></ul><p class="d-note">Harmonogram nie wymaga ręcznych zmian przez cały rok.</p></article></div></section>`
 + dSec('Zakres', 'Pełna autonomia albo *samo oświetlenie.*', `<div class="d-tiers" data-reveal><article class="tile"><h3>Tylko oświetlenie</h3><p>Na nowej inwestycji albo istniejącym korcie, gdy nie potrzebujesz automatyki wszystkich elementów.</p><ul class="k-list"><li>Automatyczne sterowanie światłem</li><li>Harmonogram wschód / zachód słońca</li><li>Sterowanie manualne</li></ul></article><article class="tile d-tier-full"><span class="k-tag">Pełny zakres</span><h3>Pełna autonomia</h3><p>Kort działa bez stałej obsługi recepcji przy kolejnych rezerwacjach.</p><ul class="k-list"><li>Automatyczny dostęp</li><li>Inteligentne oświetlenie</li><li>Sygnały dźwiękowe</li><li>Przycisk bezpieczeństwa</li><li>Sterowanie manualne</li></ul></article></div>`)
 + dSec('Dla kogo', 'Autonomia dla *różnych modeli inwestycji.*', tiles([['Inwestorzy', 'Model ograniczający liczbę procesów wymagających stałej obsługi na miejscu.'], ['Mniejsze miejscowości', 'Kort może działać tam, gdzie stała recepcja byłaby nieproporcjonalna do skali inwestycji.'], ['Hotele i resorty', 'Szersza oferta sportowa bez osobnej recepcji tylko do obsługi kortu.'], ['Istniejące obiekty i kluby', 'Wdrożenie przy rozbudowie albo na istniejącym korcie, jeśli pozwalają na to warunki techniczne.'], ['Właściciele terenów', 'Nowa funkcja sportowa i komercyjna dla posiadanej lokalizacji.']], 'five'))
 + `<section class="dark-section k-sec"><div class="wrap k-split"><div><span class="eyebrow">Korzyści</span>${kin('Więcej możliwości przy *mniejszej liczbie procesów.*')}</div><ul class="k-why" data-reveal>${[['Mniejsza zależność od recepcji', 'Kolejne rezerwacje nie wymagają pracownika tylko po to, by otworzyć kort.'], ['Elastyczne godziny', 'Dostępność kortu nie zależy od godzin pracy recepcji.'], ['Niższe koszty stałej obsługi', 'Mniej potrzeby zatrudniania osoby wyłącznie do obsługi dostępu.'], ['Mniejsze lokalizacje', 'Model atrakcyjny także poza największymi miastami.'], ['Skalowanie', 'Od pojedynczego kortu po inwestycję z kilkoma kortami.'], ['Planowanie z kortem', 'Najpełniejsze rozwiązanie, gdy autonomia jest w projekcie od początku. Istniejący kort też sprawdzimy.']].map(([t, d]) => `<li><b>${t}</b><span>${d}</span></li>`).join('')}</ul></div></section>`
 + dSec('Realizacje', 'Autonomia *w praktyce.*', tiles([['PadelBox Cupra Wspólna', 'Rzeszów · pełna automatyka', '<div class="d-tags"><span>Automatyczny dostęp</span><span>Oświetlenie</span><span>Sygnały dźwiękowe</span><span>System bezpieczeństwa</span></div>'], ['PadelBox Bulwary', 'Rzeszów · automatyka oświetlenia', '<div class="d-tags"><span>Automatyczne oświetlenie</span><span>Sterowanie manualne</span></div>'], ['Antuka Częstochowa', 'Częstochowa · pełna automatyka', '<div class="d-tags"><span>Automatyczny dostęp</span><span>Oświetlenie</span><span>Sygnały dźwiękowe</span></div>']]))
 + faqSec([['Czym jest autonomiczny kort do padla?', 'To kort wyposażony w system automatyki, który pozwala ograniczyć konieczność stałej obsługi recepcji. System steruje między innymi dostępem do kortu, oświetleniem oraz sygnałami informującymi o zakończeniu czasu gry.'], ['Czym taki kort różni się od standardowego kortu?', 'Standardowy kort wymaga ręcznej obsługi części procesów związanych z jego funkcjonowaniem. W autonomicznym korcie wybrane czynności wykonywane są automatycznie zgodnie z ustalonym harmonogramem.'], ['Jak gracze wiedzą, że kończy się ich rezerwacja?', 'Po zakończeniu rezerwacji system wykorzystuje sekwencję sygnałów dźwiękowych. Pierwsze sygnały pojawiają się po około 3 minutach, następne po 4 minutach, a około 5 minut po zakończeniu rezerwacji emitowany jest długi sygnał końcowy.'], ['Co jeśli zostanę na korcie po zamknięciu drzwi?', 'Przycisk bezpieczeństwa znajdujący się wewnątrz umożliwia otwarcie drzwi i bezpieczne opuszczenie kortu.'], ['Czy mogę sterować kortem manualnie?', 'Tak. W razie potrzeby można ręcznie sterować wybranymi elementami infrastruktury, między innymi otwieraniem drzwi oraz oświetleniem.'], ['Czy mogę zastosować system na istniejącym korcie?', 'Tak. Najpierw NeoPadel musi sprawdzić istniejącą infrastrukturę i ocenić możliwości techniczne wdrożenia automatyki.'], ['Czy lepiej zaplanować system już podczas budowy kortu?', 'Tak. Realizacja projektowana od podstaw pozwala odpowiednio przygotować całą infrastrukturę pod system automatyki już na etapie powstawania obiektu.'], ['Czy mogę wdrożyć tylko automatyczne sterowanie światłem?', 'Tak. Nie trzeba wdrażać pełnego systemu autonomicznego. NeoPadel może zastosować również samo rozwiązanie do automatycznego sterowania oświetleniem.'], ['Czy autonomiczny kort nie wymaga żadnej obsługi?', 'Automatyka ogranicza przede wszystkim procesy wymagające stałej obecności przy kolejnych rezerwacjach. Fizyczny obiekt nadal wymaga odpowiedniego utrzymania, sprzątania, konserwacji i okresowego serwisu.']])
 + final('Planujesz nową inwestycję albo chcesz zautomatyzować istniejący obiekt?', 'Porozmawiajmy o *autonomicznym korcie.*', bigCta('Zacznij z NeoPadel') + contactLinks);

const shop = () => dHero('Sklep afiliacyjny dla klubów', 'Więcej niż rezerwacja. *Nowe źródło przychodu.*', 'Daj graczom dostęp do sprzętu padlowego i zarabiaj prowizję od sprzedaży, bez własnego magazynu i logistyki. NeoPadel obsługuje zamówienia, płatności, wysyłkę i zwroty.', `${link('Uruchom sklep w swoim klubie', 'kontakt')}<a class="text-link" href="#jak-sklep">Zobacz, jak to działa</a>`)
 + `<section class="dark-section d-proof"><div class="wrap"><div class="d-tags big" data-reveal><span>Bez własnego magazynu</span><span>Prowizja od sprzedaży</span><span>Logistyka po stronie NeoPadel</span><span>Sprzedaż online i w klubie</span></div></div></section>`
 + dSec('Główna korzyść', 'Kort to dopiero *początek relacji z graczem.*', `<p class="k-lead d-lead">Gracz przychodzi grać, a przy okazji potrzebuje rakiety, piłek, obuwia, odzieży i akcesoriów. Ty dajesz graczom dostęp do oferty. NeoPadel realizuje zamówienie.</p>${chain(['Gracz', 'Klub', 'Sklep', 'Zakup', 'Realizacja', 'Prowizja dla klubu'])}`)
 + `<section class="dark-section k-sec" id="jak-sklep"><div class="wrap"><div class="k-head"><span class="eyebrow">Jak to działa</span>${kin('Sklep afiliacyjny *w czterech krokach.*','h2','accent')}</div>${steps([['Dołączasz do programu', 'Dostajesz materiały promocyjne, kod QR i link referencyjny.'], ['Punkt sprzedaży w klubie', 'Mobilny punkt na tablecie: gracze przeglądają ofertę i zamawiają na miejscu.'], ['Gracz wybiera i kupuje', 'Płatność i obsługa zamówienia w ramach rozwiązania NeoPadel.'], ['NeoPadel realizuje zamówienie', 'Logistyka, wysyłka i zwroty. Dostawa do domu albo odbiór w klubie. Klub dostaje prowizję.']])}</div></section>`
 + dSec('Sprzedaż w wielu miejscach', 'Sprzedawaj sprzęt *bez zapełniania magazynu.*', tiles([['Tablet w klubie', 'Zagraj. Wybierz sprzęt. Zamów. Gracz składa zamówienie podczas wizyty w obiekcie.'], ['Kod QR', 'Umieść go w przestrzeni klubu i pozwól graczom przejść prosto do oferty.'], ['Link referencyjny', 'Udostępniaj go w kanałach online: Instagram, Facebook, newsletter, strona klubu.'], ['Materiały promocyjne', 'Gotowe materiały do informowania klientów o dostępnej ofercie.']]))
 + dSec('Kategorie', 'Wszystko, czego gracz *potrzebuje na korcie.*', tiles([['Rakiety do padla', 'Modele dla graczy o różnych potrzebach i poziomie.'], ['Buty', 'Przyczepność, komfort i ruch po korcie.'], ['Odzież sportowa', 'Koszulki, spodenki i inne elementy do gry.'], ['Piłki i akcesoria', 'Piłki, owijki, torby i akcesoria.'], ['Sprzęt treningowy', 'Także maszyny do wyrzucania piłek.'], ['Odzież z logo klubu', 'Rozpoznawalność marki i społeczność wokół obiektu.']]))
 + `<section class="dark-section k-sec"><div class="wrap"><div class="k-head"><span class="eyebrow">Dostawa i obowiązki</span>${kin('Zamów online. *Odbierz przy kolejnej grze.*')}</div><div class="d-two" data-reveal><article class="tile"><h3>Twój klub</h3><ul class="k-list"><li>Udostępnia sklep swoim graczom</li><li>Promuje ofertę w klubie i własnych kanałach</li><li>Buduje relację ze społecznością graczy</li><li>Korzysta z dodatkowego kanału przychodu</li></ul></article><article class="tile"><h3>NeoPadel</h3><ul class="k-list"><li>Obsługuje zamówienia i płatności</li><li>Organizuje wysyłkę i logistykę</li><li>Obsługuje zwroty</li><li>Zapewnia rozwiązania wspierające sprzedaż</li><li>Dostawa do domu albo odbiór w klubie</li></ul></article></div></div></section>`
 + dSec('Porównanie', 'Rozszerz ofertę bez budowania *sklepu od podstaw.*', `<div class="d-compare" data-reveal><div class="d-row d-row-h"><span>Tradycyjny sklep klubowy</span><span>Sklep afiliacyjny NeoPadel</span></div>${[['Zakup towaru przed sprzedażą', 'Bez własnego zatowarowania'], ['Potrzebna przestrzeń magazynowa', 'Bez własnego magazynu'], ['Własna organizacja wysyłki', 'Logistyka po stronie NeoPadel'], ['Własna obsługa zwrotów', 'Zwroty obsługuje NeoPadel'], ['Kapitał związany w towarze', 'Prowizja od sprzedaży']].map(([a, b]) => `<div class="d-row"><span>${a}</span><span>${b}</span></div>`).join('')}</div>`)
 + faqSec([['Czy muszę mieć własny magazyn?', 'Nie. Jednym z głównych założeń rozwiązania NeoPadel jest możliwość sprzedaży sprzętu bez konieczności magazynowania go przez klub.'], ['Kto zajmuje się wysyłką?', 'Logistyka oraz wysyłka zamówień są realizowane przez NeoPadel.'], ['Kto obsługuje płatności i zwroty?', 'NeoPadel obsługuje zamówienia, płatności, wysyłkę oraz zwroty w ramach tego modelu.'], ['Czy klient może odebrać zamówienie w moim klubie?', 'Tak. Klient może wybrać dostawę do domu lub odbiór zamówienia w klubie.'], ['Czy otrzymam materiały do promocji sklepu?', 'Tak: materiały promocyjne, kod QR oraz link referencyjny dla partnera.'], ['Czy mogę sprzedawać odzież z logo mojego klubu?', 'Oferta obejmuje możliwość sprzedaży odzieży sportowej z logo klubu.'], ['Ile wynosi prowizja?', 'Szczegółowe warunki prowizji są ustalane indywidualnie. Skontaktuj się z zespołem NeoPadel, aby poznać aktualne warunki współpracy.'], ['Ile kosztuje uruchomienie sklepu?', 'Warunki finansowe są przedstawiane indywidualnie w ramach rozmowy o współpracy.']])
 + final('Sprzedaż dla gracza. Prowizja dla klubu. Logistyka po stronie NeoPadel.', 'Twój klub już ma klientów. *Daj im więcej.*', bigCta('Zacznij z NeoPadel') + contactLinks);

const projects = () => dHero('Realizacje', 'Zobacz nasze *realizacje.*', 'Od pojedynczych kortów po większe obiekty padlowe. Każda realizacja zaczyna się od innej przestrzeni: lokalizacja, charakter obiektu, liczba kortów i potrzeby inwestora.', `${link('Porozmawiaj o swojej inwestycji', 'kontakt')}${link('Poznaj ofertę budowy kortów', 'korty')}`)
 + `<section class="dark-section k-sec"><div class="wrap d-projects">${PROJECTS.map((p, i) => { const img = /super/i.test(p.model) ? 'super' : 'panorama'; return `<article class="d-project" data-reveal><div class="d-project-vis"><img src="${asset(`korty/${img}.jpg`)}" alt="Model kortu ${p.model}" width="640" height="360" loading="lazy"><span>Model ${p.model}</span></div><div><small class="k-meta">${p.city} · 2024</small><h3>${p.name}</h3><dl class="d-facts"><div><dt>Liczba kortów</dt><dd>${p.courts}</dd></div><div><dt>Model</dt><dd>${p.model}</dd></div><div><dt>Rok</dt><dd>2024</dd></div></dl><p>${p.about}</p></div></article>`; }).join('')}<p class="real-note keep">Grafiki pokazują model kortu, nie zdjęcia z realizacji.</p></div></section>`
