const players = () => dHero('Dla graczy', 'Znajdź. Zarezerwuj. *Zagraj.*', 'Sprawdzaj dostępne korty, wybieraj terminy, rezerwuj i płać z telefonu. Zapisuj się na wydarzenia, dołączaj do otwartych meczów i poznawaj ludzi z klubu.', `<a class="button glow-btn" href="https://neopadel.app/pl">Znajdź kort</a>`, `<div class="d-phones" data-reveal>${appShot('start', 'Ekran główny aplikacji NeoPadel')}${appShot('rezerwacja', 'Wybór terminu w aplikacji NeoPadel')}</div>`)
 + dSec('W aplikacji', 'Padel *pod ręką.*', tiles([['Rezerwacje kortów', 'Wolne terminy Twoich klubów w jednym miejscu.'], ['Płatności online', 'Płacisz za grę przy rezerwacji.'], ['Wydarzenia i turnieje', 'Zapisy, płatność i lista uczestników w aplikacji.'], ['Otwarte mecze', 'Brakuje jednej osoby? Dołącz do meczu i zapłać za swoje miejsce.'], ['Społeczność', 'Posty klubów i graczy, znajomi i ulubione kluby.'], ['Historia gry', 'Twoje rezerwacje i najważniejsze informacje z telefonu.']]))
 + `<section class="dark-section k-sec a-stores"><div class="wrap a-stores-in"><div><span class="eyebrow">Pobierz aplikację</span>${kin('Na iPhone *i Androida.*')}</div>${stores}</div></section>`;

const download = () => dHero('Aplikacja NeoPadel', 'Twój następny mecz *zaczyna się tutaj.*', 'Pobierz aplikację albo zarezerwuj kort w przeglądarce na neopadel.app.', stores.replace('data-reveal', '') + `<a class="text-link" href="https://neopadel.app/pl">Rezerwuj w przeglądarce</a>`);

const about = () => dHero('O NeoPadel', 'Więcej niż korty. *Więcej niż aplikacja.*', 'NeoPadel tworzy kompleksowy ekosystem dla świata padla: aplikację do rezerwacji, budowę infrastruktury, rozwiązania dla klubów, turnieje, sprzęt i społeczność graczy. Pomagamy przejść od pomysłu do działania.', `${link('Aplikacja dla klubów', 'aplikacja')}${link('Korty i budowa', 'korty')}`)
 + dSec('Ekosystem', 'Jeden ekosystem. *Wszystko w jednym miejscu.*', tiles([['Aplikacja', 'Rezerwacje, płatności, historia i dostęp do kortów z telefonu.'], ['Infrastruktura', 'Budowa kortów, hal, oświetlenia i kompletnych obiektów.'], ['Turnieje', 'Organizacja i zapisy na wydarzenia dla każdego poziomu.'], ['Społeczność', 'Gracze, kluby i partnerzy w jednym ekosystemie.']], 'four'))
 + `<section class="dark-section k-sec"><div class="wrap k-split"><div><span class="eyebrow">Dlaczego NeoPadel</span>${kin('Dla graczy *i dla biznesu.*')}</div><ul class="k-why" data-reveal>${[['Jeden ekosystem', 'Aplikacja, korty, rozwiązania dla klubów, wydarzenia, sprzęt i społeczność.'], ['Dla graczy i biznesu', 'Łączymy potrzeby grających z tym, czego potrzebują kluby i inwestorzy.'], ['Technologia dla padla', 'System wspiera rezerwacje i zarządzanie klubem.'], ['Kompleksowe podejście', 'Od budowy kortu po funkcjonowanie obiektu.'], ['Społeczność', 'Łączymy graczy i kluby przez platformę, wydarzenia i rozwój padla w Polsce.'], ['Produkcja w Polsce', 'Biuro i zespół w Piasecznie, montaż w całej Polsce.']].map(([t, d]) => `<li><b>${t}</b><span>${d}</span></li>`).join('')}</ul></div></section>`
 + `<section class="dark-section k-sec"><div class="wrap"><div class="k-head"><span class="eyebrow">Zespół</span>${kin('Ludzie, którzy *stoją za NeoPadel.*','h2','accent')}<p class="k-lead">Doświadczenie biznesowe, sportowe i technologiczne w jednym zespole.</p></div>${teamGrid()}</div></section>`;

const knowledge = () => dHero('Wiedza', 'Dobry klub zaczyna się *od dobrych decyzji.*', 'Poradniki o budowie kortów, prowadzeniu klubu i rozwoju padlowego biznesu.')
 + `<section class="dark-section k-sec"><div class="wrap"><div class="d-articles" data-reveal>${ARTICLES.map((a, i) => `<a class="tile" href="#/artykul-${i}"><small class="k-meta">${a.category} · ${a.date}</small><h3>${a.title}</h3><span class="text-link">Czytaj</span></a>`).join('')}</div></div></section>`;

const opinions = () => dHero('Opinie', 'Poznaj doświadczenia *naszych klientów.*', 'Głosy właścicieli klubów, inwestorów i graczy, pokazane w kontekście rozwiązania, z którego korzystają.')
 + `<section class="dark-section k-sec"><div class="wrap"><p class="notice d-notice">Treści z dotychczasowego projektu strony. Przed publikacją wymagają potwierdzenia i autoryzacji.</p><div class="d-quotes" data-reveal>${OPINIONS.map(o => `<blockquote class="tile"><p>„${escapeHtml(o.quote)}”</p><small>${escapeHtml(o.role)}${o.company ? ' · ' + escapeHtml(o.company) : ''}</small></blockquote>`).join('')}</div></div></section>`
