  nodes.forEach(p=>{const g=p.lit,[x,y]=pos(p);ctx.fillStyle=`rgba(${Math.round(150+g*90)},${Math.round(110+g*20)},${Math.round(220+g*20)},${.4+g*.6})`;ctx.beginPath();ctx.arc(x,y,p.r+g*1.2,0,Math.PI*2);ctx.fill();if(g>.3){ctx.fillStyle=`rgba(226,92,232,${g*.14})`;ctx.beginPath();ctx.arc(x,y,p.r*4*g,0,Math.PI*2);ctx.fill()}});
